import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  CalendarDays, 
  Clock, 
  BookOpen,
  Loader2,
  AlertCircle,
  X
} from 'lucide-react';
import type { StudentClass } from '@/types';
import { useAuth } from '@/contexts/AuthContext';
import { useTranslation } from '@/contexts/LanguageContext';
import { useLecturerClasses } from '@/hooks/useClasses';
import { extractString, extractDate } from '@/utils/sqlNull';
import AttendanceModal from '@/components/modals/AttendanceModal';

type Day = 'Monday' | 'Tuesday' | 'Wednesday' | 'Thursday' | 'Friday';

interface ScheduleItem {
  id: string;
  day: Day;
  startTime: string; // HH:mm
  endTime: string;   // HH:mm
  courseCode: string;
  courseName: string;
  className: string;
  credits: number;
  room: string;
  topic: string;
  weekNumber: number;
  classId: number;
  actualDate?: Date; // Store the actual meeting date
  meetingId: number;
}

// Helper to extract day name from date string
const getDayFromDate = (dateValue: unknown): Day | null => {
  const date = extractDate(dateValue as any);
  if (!date) return null;
  const dayIndex = date.getDay();
  const daysMap: Record<number, Day> = {
    1: 'Monday',
    2: 'Tuesday',
    3: 'Wednesday',
    4: 'Thursday',
    5: 'Friday',
  };
  return daysMap[dayIndex] || null;
};

// Helper to extract time (HH:mm) from jam_pertemuan which can be time-only or ISO datetime
const getTimeFromDate = (dateValue: unknown): string => {
  const dateStr = extractString(dateValue as any);
  if (!dateStr) return '00:00';

  const timeOnlyMatch = dateStr.match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);
  if (timeOnlyMatch) {
    const hh = timeOnlyMatch[1].padStart(2,'0');
    const mm = timeOnlyMatch[2];
    return `${hh}:${mm}`;
  }

  const afterT = dateStr.split('T')[1];
  if (afterT) {
    const part = afterT.split('.')[0].split('Z')[0];
    const [hh = '00', mm = '00'] = part.split(':');
    return `${hh.padStart(2,'0')}:${mm.padStart(2,'0')}`;
  }

  try {
    const d = new Date(dateStr);
    if (!isNaN(d.getTime())) {
      return d.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: false });
    }
  } catch {}

  return '00:00';
};

const ClassSchedule: React.FC = () => {
  const { user, currentSemester } = useAuth();
  const { t } = useTranslation();
  const navigate = useNavigate();
  const [classes, setClasses] = useState<StudentClass[]>([]);
  const [scheduleItems, setScheduleItems] = useState<ScheduleItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedMeeting, setSelectedMeeting] = useState<{
    meetingId: number;
    classId: number;
    title: string;
    subtitle: string;
    dateLabel?: string;
    meetingDateTime?: Date;
    topic?: string;
  } | null>(null);
  
  // Filter and sort state for List of Schedules
  const [selectedCourses, setSelectedCourses] = useState<string[]>([]);
  const [filterStartDate, setFilterStartDate] = useState<string>('');
  const [filterEndDate, setFilterEndDate] = useState<string>('');

  const { data: lecturerClasses, isLoading: isClassesLoading, error: classesError } = useLecturerClasses(
    user?.employeeId,
    React.useMemo(() => {
      const params: { semester?: string; start_day?: string; end_day?: string } = {};
      if (currentSemester) params.semester = currentSemester;
      if (filterStartDate) params.start_day = filterStartDate;
      if (filterEndDate) params.end_day = filterEndDate;
      return params;
    }, [currentSemester, filterStartDate, filterEndDate])
  );

  useEffect(() => {
    // Loading depends on classes loading and semester availability
    setLoading(isClassesLoading || !currentSemester);
  }, [isClassesLoading, currentSemester]);

  useEffect(() => {
    if (classesError) {
      setError(classesError instanceof Error ? classesError.message : String(classesError));
    } else {
      setError(null);
    }
  }, [classesError]);

  useEffect(() => {
    if (Array.isArray(lecturerClasses)) {
      setClasses(lecturerClasses);
    } else if (lecturerClasses) {
      setClasses([]);
    }
  }, [lecturerClasses]);

  // Process classes data whenever classes changes
  useEffect(() => {
    // Convert meeting schedules to schedule items
    const items: ScheduleItem[] = [];
    classes.forEach(classData => {
      classData.meeting_schedules?.forEach(meeting => {
        const day = getDayFromDate(meeting.tgl_pertemuan);
        
        // Skip if day is Saturday or Sunday (null)
        if (!day) return;
        
        const startTime = getTimeFromDate(meeting.jam_pertemuan);
        const actualDate = extractDate(meeting.tgl_pertemuan as any);
        
        // Skip if no valid date
        if (!actualDate) return;
        
        // Calculate end time based on credits (assuming 1 SKS = 50 minutes)
        const totalSKS = classData.sks_tatap_muka + classData.sks_praktek + classData.sks_prak_lapangan + classData.sks_simulasi;
        const durationMinutes = totalSKS * 60;
        
        // Parse start time and add duration
        const [startHours, startMinutes] = startTime.split(':').map(Number);
        const totalMinutes = startHours * 60 + startMinutes + durationMinutes;
        const endHours = Math.floor(totalMinutes / 60) % 24;
        const endMinutes = totalMinutes % 60;
        const endTime = `${String(endHours).padStart(2, '0')}:${String(endMinutes).padStart(2, '0')}`;

        items.push({
          id: `${classData.kelas_id}-${meeting.id}`,
          day,
          startTime,
          endTime,
          courseCode: classData.kode_mk,
          courseName: classData.nama_mk,
          className: classData.nama_kelas,
          credits: totalSKS,
          room: extractString(meeting.media_pembelajaran, 'TBA'),
          topic: extractString(meeting.topik, ''),
          weekNumber: meeting.pertemuan_ke,
          classId: classData.kelas_id ?? 0,
          actualDate,
          meetingId: meeting.id,
        });
      });
    });
    setScheduleItems(items);
  }, [classes]);

  if (loading || !currentSemester) {
    return (
      <div className="max-w-7xl mx-auto space-y-6">
        <div className="flex items-center justify-center h-64">
          <div className="text-center">
            <Loader2 className="h-8 w-8 animate-spin text-primary-600 mx-auto mb-2" />
            <p className="text-gray-600">{!currentSemester ? 'Loading semester information...' : 'Loading class schedule...'}</p>
          </div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="max-w-7xl mx-auto space-y-6">
        <h1 className="text-2xl font-bold text-gray-900">Class Schedule</h1>
        <div className="card bg-red-50 border-red-200">
          <div className="flex items-center space-x-3 text-red-800">
            <AlertCircle className="h-5 w-5 flex-shrink-0" />
            <div>
              <p className="font-medium">Error loading schedule</p>
              <p className="text-sm mt-1">{error}</p>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto space-y-4 lg:space-y-6">
      <h1 className="text-xl lg:text-2xl font-bold text-gray-900">Class Schedule</h1>

      {/* Summary */}
      <div className="card grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3 lg:gap-4">
        <div className="flex items-center space-x-3">
          <CalendarDays className="h-5 w-5 text-primary-600 flex-shrink-0" />
          <div>
            <div className="text-xs lg:text-sm text-gray-500">Classes Teaching</div>
            <div className="text-base lg:text-lg font-semibold">{classes.length} classes</div>
          </div>
        </div>
        <div className="flex items-center space-x-3">
          <Clock className="h-5 w-5 text-green-600 flex-shrink-0" />
          <div>
            <div className="text-xs lg:text-sm text-gray-500">Total Meetings</div>
            <div className="text-base lg:text-lg font-semibold">{scheduleItems.length} sessions</div>
          </div>
        </div>
        <div className="flex items-center space-x-3 sm:col-span-2 lg:col-span-1">
          <BookOpen className="h-5 w-5 text-blue-600 flex-shrink-0" />
          <div>
            <div className="text-xs lg:text-sm text-gray-500">Total Credits</div>
            <div className="text-base lg:text-lg font-semibold">
              {classes.reduce((sum, c) => sum + c.sks_tatap_muka + c.sks_praktek + c.sks_prak_lapangan + c.sks_simulasi, 0)} SKS
            </div>
          </div>
        </div>
      </div>

      {classes.length === 0 ? (
        <div className="card text-center py-12">
          <CalendarDays className="h-12 w-12 text-gray-400 mx-auto mb-4" />
          <h3 className="text-lg font-medium text-gray-900 mb-2">No Classes Found</h3>
          <p className="text-gray-600">
            You are not assigned to any classes for this semester.
          </p>
        </div>
      ) : (
        <>
          {/* Class List */}
          <div className="card">
            <h2 className="text-base lg:text-lg font-semibold text-gray-900 mb-3 lg:mb-4">Teaching Classes</h2>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3">
              {classes.map(classData => {
                const totalSKS = classData.sks_tatap_muka + classData.sks_praktek + classData.sks_prak_lapangan + classData.sks_simulasi;
                const meetingCount = classData.meeting_schedules?.length || 0;
                
                return (
                  <div 
                    key={classData.kelas_id} 
                    onClick={() => {
                      navigate(`/class-summary/${classData.kelas_id}?courseCode=${encodeURIComponent(classData.kode_mk)}&courseName=${encodeURIComponent(classData.nama_mk)}&className=${encodeURIComponent(classData.nama_kelas)}&sksTatapMuka=${classData.sks_tatap_muka}&sksPraktek=${classData.sks_praktek}&sksPrakLapangan=${classData.sks_prak_lapangan}&sksSimulasi=${classData.sks_simulasi}&from=lecturer/class-schedule`);
                    }}
                    className="p-3 border border-gray-200 rounded-lg hover:bg-gray-50 transition-colors flex flex-col cursor-pointer"
                  >
                    <div className="flex-1">
                      <div className="text-xs font-medium text-primary-600 mb-1">
                        {classData.kode_mk}
                      </div>
                      <h3 className="font-semibold text-sm text-gray-900 mb-1 line-clamp-2">
                        {classData.nama_mk}
                      </h3>
                      <div className="text-xs text-gray-600 mb-2">
                        Class {classData.nama_kelas}
                      </div>
                    </div>
                    <div className="flex items-center flex-wrap gap-x-2 gap-y-0.5 text-xs text-gray-500 border-t border-gray-100 pt-2">
                      <span className="flex items-center gap-1">
                        <BookOpen className="h-3 w-3" />
                        {totalSKS} SKS
                      </span>
                      <span>•</span>
                      <span className="flex items-center gap-1">
                        <CalendarDays className="h-3 w-3" />
                        {meetingCount} meetings
                      </span>
                      {classData.mode_kuliah && (
                        <>
                          <span>•</span>
                          <span className={`px-1.5 py-0.5 rounded text-xs font-medium ${
                            classData.mode_kuliah === 'Online' ? 'bg-blue-100 text-blue-700' :
                            classData.mode_kuliah === 'Offline' ? 'bg-green-100 text-green-700' :
                            'bg-purple-100 text-purple-700'
                          }`}>
                            {classData.mode_kuliah}
                          </span>
                        </>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* List of Schedules */}
          <div className="card">
            <div className="flex items-center justify-between mb-3 lg:mb-4 flex-wrap gap-3">
              <h2 className="text-base lg:text-lg font-semibold text-gray-900">Meeting Schedule</h2>
            </div>

            {/* Filter and Sort Controls */}
            <div className="mb-4 lg:mb-6 pb-3 lg:pb-4 border-b border-gray-200">
              <div className="space-y-4">
                {/* Course Filter */}
                <div>
                  <label className="block text-xs font-semibold text-gray-700 mb-2 lg:mb-3">{t('student.filterByCourse')}</label>
                  <div className="flex gap-2 flex-wrap">
                    {Array.from(new Set(scheduleItems.map(item => item.courseCode))).map(code => {
                      const isSelected = selectedCourses.includes(code);
                      const courseName = scheduleItems.find(item => item.courseCode === code)?.courseName || code;
                      
                      return (
                        <button
                          key={code}
                          onClick={() => {
                            if (isSelected) {
                              setSelectedCourses(selectedCourses.filter(c => c !== code));
                            } else {
                              setSelectedCourses([...selectedCourses, code]);
                            }
                          }}
                          className={`px-2 py-1 text-xs font-medium rounded-lg transition-colors ${
                            isSelected
                              ? 'bg-primary-600 text-white'
                              : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                          }`}
                        >
                          {/* On small screens show course name only; on larger screens show code — name */}
                          <span className="sm:hidden">{courseName}</span>
                          <span className="hidden sm:inline">{code} — {courseName}</span>
                        </button>
                      );
                    })}
                    {selectedCourses.length > 0 && (
                      <button
                        onClick={() => setSelectedCourses([])}
                        className="px-2 py-1 text-xs font-medium text-red-600 hover:text-red-700 hover:bg-red-50 rounded-lg transition-colors"
                      >
                        Clear
                      </button>
                    )}
                  </div>
                </div>

                {/* Date Filter */}
                <div>
                  <label className="block text-xs font-semibold text-gray-700 mb-2 lg:mb-3">{t('student.filterByDate')}</label>
                  <div className="flex flex-col sm:flex-row gap-2 sm:gap-3">
                    <div className="flex-1">
                      <input
                        type="date"
                        value={filterStartDate}
                        onChange={(e) => setFilterStartDate(e.target.value)}
                        className="input-field w-full text-xs"
                        placeholder="Start date"
                      />
                    </div>
                    <div className="flex-1">
                      <input
                        type="date"
                        value={filterEndDate}
                        onChange={(e) => setFilterEndDate(e.target.value)}
                        className="input-field w-full text-xs"
                        placeholder="End date"
                      />
                    </div>
                    {(filterStartDate || filterEndDate) && (
                      <button
                        onClick={() => {
                          setFilterStartDate('');
                          setFilterEndDate('');
                        }}
                        className="px-3 py-2 text-xs font-medium text-red-600 hover:text-red-700 hover:bg-red-50 rounded-lg transition-colors flex items-center gap-1 justify-center"
                      >
                        <X className="h-3 w-3" />
                        Clear
                      </button>
                    )}
                  </div>
                </div>
              </div>
            </div>

            {/* Schedule Table */}
            {(() => {
              let filtered = scheduleItems;
              
              if (selectedCourses.length > 0) {
                filtered = filtered.filter(item => selectedCourses.includes(item.courseCode));
              }

              // Note: Date filtering is now handled by the backend via start_day and end_day parameters

              // Sort by date
              const sorted = [...filtered].sort((a, b) => {
                if (!a.actualDate || !b.actualDate) return 0;
                
                // First, compare by date
                const dateComparison = a.actualDate.getTime() - b.actualDate.getTime();
                if (dateComparison !== 0) return dateComparison;
                
                // If dates are the same, compare by time
                return a.startTime.localeCompare(b.startTime);
              });

              if (sorted.length === 0) {
                return (
                  <div className="text-center py-12">
                    <CalendarDays className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                    <p className="text-gray-600">No meetings match the selected filters.</p>
                  </div>
                );
              }

              return (
                <div className="space-y-3">
                  {/* Mobile Card View */}
                  <div className="lg:hidden space-y-2">
                    {sorted.map((item) => {
                      // Combine date and time to create meeting datetime
                      const meetingDateTime = item.actualDate ? new Date(item.actualDate) : null;
                      if (meetingDateTime && item.startTime) {
                        const [hours, minutes] = item.startTime.split(':').map(Number);
                        meetingDateTime.setHours(hours, minutes, 0, 0);
                      }

                      return (
                      <div key={item.id} className="p-3 border border-gray-200 rounded-lg hover:bg-gray-50 transition-colors">
                        <div className="flex items-start justify-between mb-2">
                          <div className="flex-1">
                            <div className="text-xs font-medium text-primary-600 mb-1">
                              {item.courseCode} - Class {item.className}
                            </div>
                            <h3 className="font-semibold text-sm text-gray-900 mb-1">
                              {item.courseName}
                            </h3>
                          </div>
                          <button
                            onClick={() => setSelectedMeeting({
                              meetingId: item.meetingId,
                              classId: item.classId,
                              title: `${item.courseCode} • ${item.courseName}`,
                              subtitle: `Week ${item.weekNumber}`,
                              dateLabel: item.actualDate?.toLocaleDateString('id-ID', { weekday: 'short', day: 'numeric', month: 'short' }),
                              meetingDateTime: meetingDateTime || undefined,
                              topic: item.topic || undefined,
                            })}
                            className="px-2 py-1 text-xs font-medium rounded bg-primary-600 text-white hover:bg-primary-700 cursor-pointer"
                          >
                            Attendances
                          </button>
                        </div>
                        
                        <div className="space-y-1.5 text-xs text-gray-600">
                          <div className="flex items-center gap-2">
                            <CalendarDays className="h-3.5 w-3.5 flex-shrink-0" />
                            <span>
                              {item.actualDate?.toLocaleDateString('en-US', { 
                                weekday: 'short', 
                                year: 'numeric', 
                                month: 'short', 
                                day: 'numeric' 
                              })}
                            </span>
                          </div>
                          <div className="flex items-center gap-2">
                            <Clock className="h-3.5 w-3.5 flex-shrink-0" />
                            <span>{item.startTime}</span>
                          </div>
                          {item.topic && (
                            <div className="mt-2 pt-2 border-t border-gray-100">
                              <div className="font-medium text-gray-700 mb-0.5">Week {item.weekNumber}</div>
                              <div className="text-gray-600">{item.topic}</div>
                            </div>
                          )}
                        </div>
                      </div>
                      );
                    })}
                  </div>

                  {/* Desktop Table View */}
                  <div className="hidden lg:block overflow-x-auto">
                    <table className="w-full text-xs">
                      <thead>
                        <tr className="bg-gray-50 border-b border-gray-200">
                          <th className="px-3 py-2 text-left font-semibold text-gray-700">{t('lecturerSchedule.date')}</th>
                          <th className="px-3 py-2 text-left font-semibold text-gray-700">{t('lecturerSchedule.time')}</th>
                          <th className="px-3 py-2 text-left font-semibold text-gray-700">{t('lecturerSchedule.course')}</th>
                          <th className="px-3 py-2 text-left font-semibold text-gray-700">{t('lecturerSchedule.week')}</th>
                          <th className="px-3 py-2 text-left font-semibold text-gray-700">{t('lecturerSchedule.topic')}</th>
                          <th className="px-3 py-2 text-left font-semibold text-gray-700">{t('lecturerSchedule.attendances')}</th>
                        </tr>
                      </thead>
                      <tbody>
                        {sorted.map((item) => {
                          // Combine date and time to create meeting datetime
                          const meetingDateTime = item.actualDate ? new Date(item.actualDate) : null;
                          if (meetingDateTime && item.startTime) {
                            const [hours, minutes] = item.startTime.split(':').map(Number);
                            meetingDateTime.setHours(hours, minutes, 0, 0);
                          }

                          return (
                          <tr key={item.id} className="border-b border-gray-100 hover:bg-gray-50 transition-colors">
                            <td className="px-3 py-2.5">
                              <div className="flex items-center gap-1.5">
                                <CalendarDays className="h-3.5 w-3.5 text-gray-400 flex-shrink-0" />
                                <span className="text-gray-900">
                                  {item.actualDate?.toLocaleDateString('en-US', { 
                                    weekday: 'short', 
                                    month: 'short', 
                                    day: 'numeric' 
                                  })}
                                </span>
                              </div>
                            </td>
                            <td className="px-3 py-2.5">
                              <div className="flex items-center gap-1.5">
                                <Clock className="h-3.5 w-3.5 text-gray-400 flex-shrink-0" />
                                <span className="text-gray-900">{item.startTime}</span>
                              </div>
                            </td>
                            <td className="px-3 py-2.5">
                              <div>
                                <div className="font-medium text-primary-600">{item.courseCode}</div>
                                <div className="text-gray-600 line-clamp-1">{item.courseName}</div>
                              </div>
                            </td>
                            <td className="px-3 py-2.5">
                              <span className="px-2 py-1 bg-gray-100 text-gray-700 rounded font-medium">
                                {item.weekNumber}
                              </span>
                            </td>
                            <td className="px-3 py-2.5">
                              <span className="text-gray-900">{item.topic || '-'}</span>
                            </td>
                            <td className="px-3 py-2.5">
                              <button
                                onClick={() => setSelectedMeeting({
                                  meetingId: item.meetingId,
                                  classId: item.classId,
                                  title: `${item.courseCode} • ${item.courseName}`,
                                  subtitle: `Class ${item.className} • Week ${item.weekNumber}`,
                                  dateLabel: item.actualDate?.toLocaleDateString('id-ID', { weekday: 'short', day: 'numeric', month: 'short' }),
                                  meetingDateTime: meetingDateTime || undefined,
                                  topic: item.topic || undefined,
                                })}
                                className="px-2 py-1 text-xs font-medium rounded bg-primary-600 text-white hover:bg-primary-700 cursor-pointer"
                              >
                              {t('lecturerSchedule.view')}
                              </button>
                            </td>
                          </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>
                </div>
              );
            })()}
          </div>

          <AttendanceModal
            selectedMeeting={selectedMeeting}
            onClose={() => setSelectedMeeting(null)}
          />
        </>
      )}
    </div>
  );
};

export default ClassSchedule;
